import json

questions = []

def add_q(topic, q, opts, ans, exp):
    questions.append({
        "id": f"vlsi_{len(questions)+1:03d}",
        "topic": topic,
        "question": q,
        "options": opts,
        "correctIndex": ans,
        "explanation": exp
    })

